#!/usr/bin/env bash
# lib/experiment.sh — Save a resilience check, replay it headless.
# An experiment is generated by the interactive flow (never hand-written) and
# committed under experiments/. Replaying it with `nuke.sh run <name>` runs the
# same check without a menu and exits 0/1, so it becomes a CI gate: resilience
# as a merge condition, like tests.

if [[ -n "${NUKE_EXPERIMENT_LOADED:-}" ]]; then
    return 0
fi
NUKE_EXPERIMENT_LOADED=1

# Where experiments live. Relative by default so they sit in the app repo and
# travel with it into CI.
NUKE_EXPERIMENTS_DIR="${NUKE_EXPERIMENTS_DIR:-experiments}"

# Populated by nuke_experiment_load.
NUKE_EXP_NAME=""
NUKE_EXP_LAYER=""
NUKE_EXP_FAULT=""
NUKE_EXP_INTENSITY=""

nuke_experiment_dir() {
    printf '%s' "${NUKE_EXPERIMENTS_DIR}"
}

# Resolve a reference to a file path: a bare name maps to <dir>/<name>.exp; a
# path or a *.exp value is used as-is.
nuke_experiment_path() {
    local ref="$1"
    if [[ "${ref}" == */* || "${ref}" == *.exp ]]; then
        printf '%s' "${ref}"
    else
        printf '%s/%s.exp' "$(nuke_experiment_dir)" "${ref}"
    fi
}

# nuke_experiment_save <name> <layer> <fault> <intensity>
# Capture the current scope and thresholds into a generated .exp file.
nuke_experiment_save() {
    local name="$1" layer="$2" fault="$3" intensity="$4"
    local dir path
    dir="$(nuke_experiment_dir)"
    mkdir -p "${dir}"
    path="${dir}/${name}.exp"
    {
        printf 'NAME=%s\n'               "${name}"
        printf 'LAYER=%s\n'              "${layer}"
        printf 'K8S_NAMESPACE=%s\n'      "${NUKE_K8S_NAMESPACE:-}"
        printf 'K8S_LABEL=%s\n'          "${NUKE_K8S_LABEL:-}"
        printf 'FAULT=%s\n'              "${fault}"
        printf 'INTENSITY=%s\n'          "${intensity}"
        printf 'STEADY_MIN_SUCCESS=%s\n' "${NUKE_STEADY_MIN_SUCCESS:-95}"
        printf 'RECOVER_WITHIN=%s\n'     "${NUKE_RECOVER_WITHIN:-30}"
        printf 'PROBE_INTERVAL=%s\n'     "${NUKE_PROBE_INTERVAL:-2}"
    } > "${path}"
    log_success "Saved experiment: ${path}"
    log_info "Replay in CI: ./nuke.sh run ${name}"
}

# nuke_experiment_load <ref> — read a whitelist of keys into the globals.
# Anything else in the file is ignored; the file is never sourced.
nuke_experiment_load() {
    local path
    path="$(nuke_experiment_path "$1")"
    [[ -f "${path}" ]] || { log_error "Experiment not found: ${path}"; return 1; }

    NUKE_EXP_NAME=""; NUKE_EXP_LAYER=""; NUKE_EXP_FAULT=""; NUKE_EXP_INTENSITY=""
    local key val
    while IFS='=' read -r key val; do
        case "${key}" in
            NAME)               NUKE_EXP_NAME="${val}"           ;;
            LAYER)              NUKE_EXP_LAYER="${val}"          ;;
            FAULT)              NUKE_EXP_FAULT="${val}"          ;;
            INTENSITY)          NUKE_EXP_INTENSITY="${val}"      ;;
            K8S_NAMESPACE)      NUKE_K8S_NAMESPACE="${val}"      ;;
            K8S_LABEL)          NUKE_K8S_LABEL="${val}"          ;;
            STEADY_MIN_SUCCESS) NUKE_STEADY_MIN_SUCCESS="${val}" ;;
            RECOVER_WITHIN)     NUKE_RECOVER_WITHIN="${val}"     ;;
            PROBE_INTERVAL)     NUKE_PROBE_INTERVAL="${val}"     ;;
            *) : ;;
        esac
    done < "${path}"
}

# nuke_experiment_run <ref> — load and execute headless. Prints a verdict and
# returns the check's exit code (0 resilient, 1 weak, 2 could not run).
nuke_experiment_run() {
    nuke_experiment_load "$1" || return 2

    if [[ "$(nuke_level_index "${NUKE_EXP_INTENSITY}")" == "0" ]]; then
        log_error "Unknown intensity in experiment: ${NUKE_EXP_INTENSITY:-<empty>}"
        return 2
    fi

    log_step "Experiment: ${NUKE_EXP_NAME:-$1}"
    log_info "layer=${NUKE_EXP_LAYER} fault=${NUKE_EXP_FAULT} intensity=${NUKE_EXP_INTENSITY}"

    case "${NUKE_EXP_LAYER}:${NUKE_EXP_FAULT}" in
        kubernetes:pod-kill)
            k8s_available || return 2
            NUKE_SCOPE="k8s:${NUKE_K8S_NAMESPACE}"
            [[ -n "${NUKE_K8S_LABEL}" ]] && NUKE_SCOPE="${NUKE_SCOPE} (${NUKE_K8S_LABEL})"
            nuke_resilience_run k8s_steady_probe k8s_pod_kill "${NUKE_EXP_INTENSITY}" 0 "k8s pod-kill"
            return $?
            ;;
        *)
            log_error "Not runnable headless yet: ${NUKE_EXP_LAYER}/${NUKE_EXP_FAULT}"
            log_info "v1 supports kubernetes/pod-kill; more faults land next."
            return 2
            ;;
    esac
}
